def merge_categories(apps, schema_editor):
    """Turn every tafsir and translation into a text asset that keeps its kind as a tag."""
    Asset = apps.get_model("content", "Asset")
    AssetTag = apps.get_model("content", "AssetTag")
    for slug, name_en, name_ar in BUILTIN_TAGS:
        tag, _ = AssetTag.objects.update_or_create(
            slug=slug, defaults={"name": name_ar, "name_en": name_en, "name_ar": name_ar, "is_builtin": True}
        )
        ids = Asset.objects.filter(category=slug).values_list("pk", flat=True)
        Asset.tags.through.objects.bulk_create(
            [Asset.tags.through(asset_id=asset_id, assettag_id=tag.pk) for asset_id in ids], ignore_conflicts=True
        )
    Asset.objects.filter(category__in=[slug for slug, _, _ in BUILTIN_TAGS]).update(category="text")


def split_categories(apps, schema_editor):
    """Reverse: an asset tagged translation becomes a translation, every other text asset a tafsir."""
    Asset = apps.get_model("content", "Asset")
    AssetTag = apps.get_model("content", "AssetTag")
    Asset.objects.filter(category="text", tags__slug="translation").update(category="translation")
    Asset.objects.filter(category="text").update(category="tafsir")
    AssetTag.objects.all().delete()


def _permission_content_type(apps):
    ContentType = apps.get_model("contenttypes", "ContentType")
    return ContentType.objects.get_or_create(app_label="plain_permissions", model="permission")[0]


def _copy_holders(apps, sources, target):
    """Give ``target`` to every group and user holding one of ``sources``."""
    Group = apps.get_model("auth", "Group")
    User = apps.get_model("users", "User")
    GroupLink = Group.permissions.through
    UserLink = User.user_permissions.through
    source_ids = [permission.pk for permission in sources]
    group_ids = set(GroupLink.objects.filter(permission_id__in=source_ids).values_list("group_id", flat=True))
    user_ids = set(UserLink.objects.filter(permission_id__in=source_ids).values_list("user_id", flat=True))
    GroupLink.objects.bulk_create(
        [GroupLink(group_id=group_id, permission_id=target.pk) for group_id in group_ids], ignore_conflicts=True
    )
    UserLink.objects.bulk_create(
        [UserLink(user_id=user_id, permission_id=target.pk) for user_id in user_ids], ignore_conflicts=True
    )


def merge_permissions(apps, schema_editor):
    Permission = apps.get_model("auth", "Permission")
    content_type = _permission_content_type(apps)
    for codename, (tafsir, translation, name) in PERMISSION_MERGE.items():
        sources = Permission.objects.filter(content_type=content_type, codename__in=[tafsir, translation])
        if not sources.exists():
            continue  # A new database: plain_permissions creates the merged one after migrating.
        target, _ = Permission.objects.get_or_create(
            content_type=content_type, codename=codename, defaults={"name": name}
        )
        _copy_holders(apps, list(sources), target)
        sources.delete()


def split_permissions(apps, schema_editor):
    """Reverse: holders of a merged permission get both old ones back."""
    Permission = apps.get_model("auth", "Permission")
    content_type = _permission_content_type(apps)
    for codename, (tafsir, translation, _name) in PERMISSION_MERGE.items():
        merged = Permission.objects.filter(content_type=content_type, codename=codename).first()
        if merged is None:
            continue
        for old in (tafsir, translation):
            target, _ = Permission.objects.get_or_create(content_type=content_type, codename=old, defaults={"name": old})
            _copy_holders(apps, [merged], target)
        merged.delete()


